const searchPeople = `-- name: SearchPeople :many
SELECT p.id, p.name, p.creator_id, p.representative_id, p.hidden, p.revision, p.merged_into, p.created_at,f.frame_ref,s.video_id,f.sample_ts FROM people p LEFT JOIN face_observations f ON f.id=p.representative_id LEFT JOIN face_index_sets s ON s.id=f.set_id
WHERE p.merged_into IS NULL AND (NOT p.hidden OR $1::boolean) AND p.name ILIKE '%'||$2::text||'%' ORDER BY p.name,p.id LIMIT 100
`

type SearchPeopleParams struct {
	IncludeHidden bool   `db:"include_hidden" json:"IncludeHidden"`
	Query         string `db:"query" json:"Query"`
}

type SearchPeopleRow struct {
	ID               pgtype.UUID        `db:"id" json:"ID"`
	Name             string             `db:"name" json:"Name"`
	CreatorID        pgtype.UUID        `db:"creator_id" json:"CreatorID"`
	RepresentativeID pgtype.UUID        `db:"representative_id" json:"RepresentativeID"`
	Hidden           bool               `db:"hidden" json:"Hidden"`
	Revision         int32              `db:"revision" json:"Revision"`
	MergedInto       pgtype.UUID        `db:"merged_into" json:"MergedInto"`
	CreatedAt        pgtype.Timestamptz `db:"created_at" json:"CreatedAt"`
	FrameRef         *string            `db:"frame_ref" json:"FrameRef"`
	VideoID          pgtype.UUID        `db:"video_id" json:"VideoID"`
	SampleTs         *float64           `db:"sample_ts" json:"SampleTs"`
}

// SearchPeople
//
//	SELECT p.id, p.name, p.creator_id, p.representative_id, p.hidden, p.revision, p.merged_into, p.created_at,f.frame_ref,s.video_id,f.sample_ts FROM people p LEFT JOIN face_observations f ON f.id=p.representative_id LEFT JOIN face_index_sets s ON s.id=f.set_id
//	WHERE p.merged_into IS NULL AND (NOT p.hidden OR $1::boolean) AND p.name ILIKE '%'||$2::text||'%' ORDER BY p.name,p.id LIMIT 100
func (q *Queries) SearchPeople(ctx context.Context, arg *SearchPeopleParams) ([]*SearchPeopleRow, error) {
	rows, err := q.db.Query(ctx, searchPeople, arg.IncludeHidden, arg.Query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*SearchPeopleRow
	for rows.Next() {
		var i SearchPeopleRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.CreatorID,
			&i.RepresentativeID,
			&i.Hidden,
			&i.Revision,
			&i.MergedInto,
			&i.CreatedAt,
			&i.FrameRef,
			&i.VideoID,
			&i.SampleTs,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const searchVisualEmbeddings = `-- name: SearchVisualEmbeddings :many
SELECT v.id AS video_id,v.title,v.uploader,e.sample_ts,e.frame_ref,(1-(e.embedding <=> $1::text::vector))::float8 AS similarity,s.next_sample,s.interval_seconds,s.start_ts,s.end_ts,s.status
FROM visual_frame_embeddings e JOIN visual_index_sets s ON s.id=e.set_id JOIN videos v ON v.id=s.video_id LEFT JOIN channels c ON c.id=v.channel_row_id
WHERE s.model_id=$2 AND (s.active OR NOT EXISTS(SELECT 1 FROM visual_index_sets a WHERE a.video_id=s.video_id AND a.active))
AND ($3::uuid IS NULL OR v.id=$3)
AND ($4::uuid IS NULL OR v.channel_row_id=$4)
AND ($5::uuid IS NULL OR c.creator_id=$5)
ORDER BY e.embedding <=> $1::text::vector LIMIT $6
`

type SearchVisualEmbeddingsParams struct {
	Embedding      string      `db:"embedding" json:"Embedding"`
	ModelID        string      `db:"model_id" json:"ModelID"`
	VideoID        pgtype.UUID `db:"video_id" json:"VideoID"`
	ChannelID      pgtype.UUID `db:"channel_id" json:"ChannelID"`
	CreatorID      pgtype.UUID `db:"creator_id" json:"CreatorID"`
	CandidateLimit int32       `db:"candidate_limit" json:"CandidateLimit"`
}

type SearchVisualEmbeddingsRow struct {
	VideoID         pgtype.UUID `db:"video_id" json:"VideoID"`
	Title           string      `db:"title" json:"Title"`
	Uploader        string      `db:"uploader" json:"Uploader"`
	SampleTs        float64     `db:"sample_ts" json:"SampleTs"`
	FrameRef        string      `db:"frame_ref" json:"FrameRef"`
	Similarity      float64     `db:"similarity" json:"Similarity"`
	NextSample      int32       `db:"next_sample" json:"NextSample"`
	IntervalSeconds float64     `db:"interval_seconds" json:"IntervalSeconds"`
	StartTs         float64     `db:"start_ts" json:"StartTs"`
	EndTs           float64     `db:"end_ts" json:"EndTs"`
	Status          string      `db:"status" json:"Status"`
}

// SearchVisualEmbeddings
//
//	SELECT v.id AS video_id,v.title,v.uploader,e.sample_ts,e.frame_ref,(1-(e.embedding <=> $1::text::vector))::float8 AS similarity,s.next_sample,s.interval_seconds,s.start_ts,s.end_ts,s.status
