const updatePerson = `-- name: UpdatePerson :one
UPDATE people SET name=COALESCE($1,name),hidden=COALESCE($2,hidden),creator_id=COALESCE($3,creator_id),
representative_id=COALESCE($4,representative_id),revision=revision+1 WHERE id=$5 AND revision=$6 AND merged_into IS NULL RETURNING id, name, creator_id, representative_id, hidden, revision, merged_into, created_at
`

type UpdatePersonParams struct {
	Name             *string     `db:"name" json:"Name"`
	Hidden           *bool       `db:"hidden" json:"Hidden"`
	CreatorID        pgtype.UUID `db:"creator_id" json:"CreatorID"`
	RepresentativeID pgtype.UUID `db:"representative_id" json:"RepresentativeID"`
	ID               pgtype.UUID `db:"id" json:"ID"`
	Revision         int32       `db:"revision" json:"Revision"`
}

// UpdatePerson
//
//	UPDATE people SET name=COALESCE($1,name),hidden=COALESCE($2,hidden),creator_id=COALESCE($3,creator_id),
//	representative_id=COALESCE($4,representative_id),revision=revision+1 WHERE id=$5 AND revision=$6 AND merged_into IS NULL RETURNING id, name, creator_id, representative_id, hidden, revision, merged_into, created_at
func (q *Queries) UpdatePerson(ctx context.Context, arg *UpdatePersonParams) (*Person, error) {
	row := q.db.QueryRow(ctx, updatePerson,
		arg.Name,
		arg.Hidden,
		arg.CreatorID,
		arg.RepresentativeID,
		arg.ID,
		arg.Revision,
	)
	var i Person
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.CreatorID,
		&i.RepresentativeID,
		&i.Hidden,
		&i.Revision,
		&i.MergedInto,
		&i.CreatedAt,
	)
	return &i, err
}
